from dataclasses import dataclass, replace
from datetime import datetime
from functools import partial
from gzip import decompress
from hashlib import sha256
from io import BytesIO
import json
from pathlib import Path
import signal

import numpy as np
import pandas as pd
from pandas.tseries.holiday import (
    AbstractHolidayCalendar, GoodFriday, Holiday, USLaborDay, USMartinLutherKingJr,
    USMemorialDay, USPresidentsDay, USThanksgivingDay, nearest_workday, sunday_to_monday,
)
from scipy.cluster.hierarchy import leaves_list, linkage
from scipy.optimize import minimize
from scipy.spatial.distance import squareform
import yaml


ANNUAL_SESSIONS = 252
PRICE_ADJUSTMENT = (
    "Yahoo split-adjusted Close for sizing, fills and valuation. Cash distributions modeled separately. "
    "Adj Close for allocation signals and BIL returns "
    "(label of the snapshot's adjustment convention; the run itself does not call yfinance)."
)
PRICE_FIELDS = ("Close", "Adj Close", "Distribution")


class NyseHolidays(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr, USPresidentsDay, GoodFriday, USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay, USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
    ]


def nyse_sessions(start, end):
    if start.year < 2009 or end.year > 2025:
        raise ValueError("NYSE holiday and special-closure coverage is 2009–2025")
    closures = pd.DatetimeIndex(["2012-10-29", "2012-10-30", "2018-12-05", "2025-01-09"])
    holidays = NyseHolidays().holidays(start, end).union(closures)
    return pd.bdate_range(start, end, name="Date").difference(holidays)


@dataclass(frozen=True)
class Allocation:
    lookback_sessions: int
    gamma: float
    cost_bps: float
    slippage_bps: float

    def __post_init__(self):
        if type(self.lookback_sessions) is not int or self.lookback_sessions < 2:
            raise ValueError("lookback_sessions must be an integer of at least two")
        if not 0 <= self.gamma <= 1:
            raise ValueError("gamma must be between zero and one")
        if not (self.cost_bps >= 0 and self.slippage_bps >= 0 and self.friction < 0.5):
            raise ValueError("Invalid transaction cost or slippage")

    @property
    def friction(self):
        return (self.cost_bps + self.slippage_bps) / 10_000


def check_prices(prices, tickers, sessions):
    expected_columns = pd.MultiIndex.from_product([PRICE_FIELDS, tickers])
    if prices.empty or not prices.columns.equals(expected_columns):
        raise ValueError("Missing price history or unexpected field or ticker columns")
    if not prices.index.equals(sessions):
        missing = sessions.difference(prices.index)
        extra = prices.index.difference(sessions)
        raise ValueError(f"NYSE session mismatch. Missing {list(missing[:5])}, extra {list(extra[:5])}")
    for field in PRICE_FIELDS:
        values = prices[field].to_numpy(dtype=float)
        bad = ~np.isfinite(values) | (values < 0)
        if field != "Distribution":
            bad |= values == 0
        if bad.any():
            row, col = np.argwhere(bad)[0]
            raise ValueError(f"Missing or invalid {tickers[col]} {field} on {sessions[row].date()}")


def read_snapshot(snapshot, tickers, sessions):
    with BytesIO(snapshot) as source:
        prefix, fetched_at = source.readline().decode("utf-8").strip().split("=", 1)
        if prefix != "# fetched_at" or datetime.fromisoformat(fetched_at).tzinfo is None:
            raise ValueError("Invalid cache timestamp")
        prices = pd.read_csv(source, header=[0, 1], index_col=0, parse_dates=True)
    check_prices(prices, tickers, sessions)
    return prices, fetched_at, sha256(snapshot).hexdigest()


def load_config(config_path="config.yaml"):
    with open(config_path, "rb") as file:
        raw = file.read()
    return yaml.safe_load(raw), raw


def load_prices(config, config_path, tickers, start, end, sessions):
    data = config.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the Yahoo Finance snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = snapshot.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    input_digest = sha256(body).hexdigest()
    prices, fetched_at, snapshot_hash = read_snapshot(snapshot, tickers, sessions)
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: Yahoo Finance snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); Yahoo split-adjusted Close for sizing, fills and valuation, "
        "with cash distributions modeled separately and Adj Close for allocation signals and BIL returns. "
        "The script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    print(f"Price sessions: {len(prices)} ({prices.index[0].date()} to {prices.index[-1].date()})")
    return prices, fetched_at, snapshot_hash


def minimum_variance(cov):
    """Return simplex minimum-variance weights and their variance."""
    if len(cov) == 1:
        return np.ones(1), float(cov[0, 0])

    scaled = cov / np.max(np.diag(cov))
    initial = np.full(len(cov), 1 / len(cov))
    fit = minimize(
        lambda w: 0.5 * (w @ scaled @ w), initial,
        jac=lambda w: scaled @ w, method="SLSQP", bounds=[(0, 1)] * len(cov),
        constraints={"type": "eq", "fun": lambda w: w.sum() - 1, "jac": lambda w: np.ones_like(w)},
        options={"ftol": 1e-12, "maxiter": 100},
    )
    if not fit.success or not np.isfinite(fit.x).all():
        raise RuntimeError(f"Minimum-variance fit failed: {fit.message}")
    weights = np.maximum(fit.x, 0)
    weights /= weights.sum()
    return weights, float(weights @ cov @ weights)


def schur_children(cov, cut, gamma, budget_floor):
    left = cov[:cut, :cut]
    right = cov[cut:, cut:]
    if gamma == 0:
        return left, right

    cross = cov[:cut, cut:]
    left_projector = np.linalg.solve(right, cross.T).T
    right_projector = np.linalg.solve(left, cross).T
    left_loading = left_projector.sum(axis=1)
    right_loading = right_projector.sum(axis=1)
    max_loading = max(left_loading.max(), right_loading.max())
    # Use the same local gamma for both siblings and keep both budget vectors positive.
    if gamma * max_loading > 1 - budget_floor:
        gamma = (1 - budget_floor) / max_loading

    left_budget = 1 - gamma * left_loading
    right_budget = 1 - gamma * right_loading
    left_schur = left - gamma * (left_projector @ cross.T)
    right_schur = right - gamma * (right_projector @ cross)
    # Table 1's precision-domain transform equals the covariance-domain transform.
    left_adjusted = (left_schur + left_schur.T) / (2 * np.outer(left_budget, left_budget))
    right_adjusted = (right_schur + right_schur.T) / (2 * np.outer(right_budget, right_budget))
    return left_adjusted, right_adjusted


def bisect_weights(cov, gamma, leaf_size, budget_floor, minimum=None):
    if len(cov) <= leaf_size:
        weights, _ = minimum if minimum is not None else minimum_variance(cov)
        return weights

    left, right = schur_children(cov, len(cov) // 2, gamma, budget_floor)
    left_minimum = minimum_variance(left)
    right_minimum = minimum_variance(right)
    left_variance = left_minimum[1]
    right_variance = right_minimum[1]
    left_share = right_variance / (left_variance + right_variance)
    left_weights = bisect_weights(left, gamma, leaf_size, budget_floor, left_minimum)
    right_weights = bisect_weights(right, gamma, leaf_size, budget_floor, right_minimum)
    return np.concatenate((left_share * left_weights, (1 - left_share) * right_weights))


def regularized_covariance(window, shrinkage):
    sample_cov = np.cov(window, rowvar=False, ddof=1)
    variances = np.diag(sample_cov)
    if (variances <= 0).any():
        raise ValueError("Expected positive sample variance for every ETF")
    return (1 - shrinkage) * sample_cov + shrinkage * np.diag(variances)


def schur_weights(cov, gamma, leaf_size, budget_floor):
    std = np.sqrt(np.diag(cov))
    corr = np.clip(cov / np.outer(std, std), -1, 1)
    distance = np.sqrt((1 - corr) / 2)
    np.fill_diagonal(distance, 0)
    order = leaves_list(linkage(squareform(distance), method="single", optimal_ordering=True))
    ordered = bisect_weights(cov[np.ix_(order, order)], gamma, leaf_size, budget_floor)
    weights = np.empty_like(ordered)
    weights[order] = ordered
    return weights


def rebalance_schedule(index, first, last, lag):
    months = index.to_period("M")
    signal_days = np.flatnonzero(months[1:] != months[:-1])
    return {
        day + lag: day
        for day in signal_days
        if first <= day + lag < last
    }


def rolling_targets(returns, schedule, lookback_sessions, shrinkage, allocate):
    targets = {}
    for fill_day, signal_day in schedule.items():
        start = signal_day + 1 - lookback_sessions
        if start < 1:
            raise ValueError("The download period does not cover the full initial lookback")
        window = returns[start:signal_day + 1]
        targets[fill_day] = allocate(regularized_covariance(window, shrinkage))
    return targets


def schur_targets(returns, schedule, spec, config):
    allocate = partial(
        schur_weights, gamma=spec.gamma, leaf_size=config["leaf_size"], budget_floor=config["budget_vector_floor"],
    )
    return rolling_targets(returns, schedule, spec.lookback_sessions, config["shrinkage"], allocate)


def plan_changes(positions, cash, previous_close, target, cash_buffer):
    """Size fixed changes using the previous session's close and available cash."""
    sizing_value = float(positions @ previous_close) + cash
    desired = (1 - cash_buffer) * sizing_value * target / previous_close
    changes = desired - positions
    changes[np.abs(changes) * previous_close <= sizing_value * 1e-8] = 0
    changes.setflags(write=False)
    return changes


def settle_changes(planned, fill_close, cash, friction):
    """Price the entire fixed plan and return cash and gross traded value."""
    fill_values = planned * fill_close
    gross_value = float(np.abs(fill_values).sum())
    remaining = cash - float(fill_values.sum()) - gross_value * friction
    if not (np.isfinite(gross_value) and np.isfinite(remaining)):
        raise ArithmeticError("Non-finite value or cash when settling predetermined fills")
    if remaining < 0:
        raise ArithmeticError(f"Predetermined fills exceed available cash by {-remaining:.12g}")
    return remaining, gross_value


def simulate(sessions, closes, distributions, release_days, first, targets, friction, cash_buffer):
    last = len(sessions)
    positions = np.zeros(closes.shape[1])
    cash = previous_value = 1.0
    pending_distributions = 0.0
    releases = np.zeros(last)
    records = []
    for day in range(first, last):
        target = targets.get(day)
        # Lock quantities before using any fill-session inputs.
        planned = (
            plan_changes(positions, cash, closes[day - 1], target, cash_buffer)
            if target is not None else None
        )

        # The ex-date entitlement belongs to the positions carried into the session.
        accrued = float(positions @ distributions[day])
        pending_distributions += accrued
        if release_days[day] < last:
            releases[release_days[day]] += accrued
        close = closes[day]
        pre_fill_value = float(positions @ close) + cash + pending_distributions
        turnover = 0.0
        trades = 0
        cash_fraction_at_fill = None
        if planned is not None:
            try:
                cash, notional = settle_changes(planned, close, cash, friction)
            except ArithmeticError as exc:
                raise ArithmeticError(f"{sessions[day].date()}: {exc}") from exc
            positions += planned
            turnover = notional / pre_fill_value
            trades = int(np.count_nonzero(planned))
            if trades:
                cash_fraction_at_fill = cash / pre_fill_value

        # Releases are available for sizing and spending from the next session.
        cash += releases[day]
        pending_distributions = max(0.0, pending_distributions - releases[day])
        value = float(positions @ close) + cash + pending_distributions
        records.append((value / previous_value - 1, turnover, trades, cash_fraction_at_fill))
        previous_value = value
    return pd.DataFrame(
        records, index=sessions[first:], columns=["return", "turnover", "n_trades", "cash_fraction_at_fill"],
    )


def metrics(daily_results, risk_free):
    returns = daily_results["return"].to_numpy()
    if len(returns) < 2 or len(returns) != len(risk_free):
        raise ValueError("Each period needs at least two aligned daily observations")
    excess = returns - risk_free
    annual_scale = np.sqrt(ANNUAL_SESSIONS)
    volatility = returns.std(ddof=1)
    excess_volatility = excess.std(ddof=1)
    growth_curve = np.concatenate(([1.0], np.cumprod(1 + returns)))
    growth = growth_curve[-1]
    return {
        "cagr": float(growth ** (ANNUAL_SESSIONS / len(returns)) - 1),
        "ann_vol": float(volatility * annual_scale),
        "sharpe": float(annual_scale * returns.mean() / volatility) if volatility else None,
        "sharpe_excess": float(annual_scale * excess.mean() / excess_volatility) if excess_volatility else None,
        "max_drawdown": float((growth_curve / np.maximum.accumulate(growth_curve) - 1).min()),
        "total_return": float(growth - 1),
        "turnover": float(daily_results["turnover"].mean() * ANNUAL_SESSIONS),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def period_metrics(daily_results, risk_free, split):
    return {
        "is": metrics(daily_results.iloc[:split], risk_free[:split]),
        "oos": metrics(daily_results.iloc[split:], risk_free[split:]),
        "full": metrics(daily_results, risk_free),
    }


def main():
    config, _ = load_config()
    universe = config["universe"]
    reference = config["risk_free_ticker"]
    if len(universe) < 2 or len(set(universe)) != len(universe) or reference in universe:
        raise ValueError("Use a distinct risk-free ticker and at least two different assets")
    if config["rebalance"] != "monthly":
        raise ValueError("Expected a monthly rebalance")
    lag = config["execution_lag_sessions"]
    if type(lag) is not int or lag < 1:
        raise ValueError("execution_lag_sessions must be a positive integer")
    cash_buffer = config["cash_buffer"]
    if not 0 < cash_buffer < 1:
        raise ValueError("cash_buffer must be strictly between zero and one")
    cash_release_days = config["distribution_cash_delay_days"]
    if type(cash_release_days) is not int or cash_release_days < 1:
        raise ValueError("distribution_cash_delay_days must be a positive integer")
    if not (0 < config["shrinkage"] <= 1 and 0 < config["budget_vector_floor"] < 1):
        raise ValueError("Invalid shrinkage or budget vector floor")
    if type(config["leaf_size"]) is not int or not 1 <= config["leaf_size"] < len(universe):
        raise ValueError("leaf_size must allow at least one split")

    dates = config["dates"]
    download_start, start, is_end, end = (pd.Timestamp(dates[k]) for k in ("download_start", "start", "is_end", "end"))
    if not download_start < start < is_end < end:
        raise ValueError("Expected download_start < start < is_end < end")
    official = Allocation(**config["allocation"])
    variants = {name: replace(official, **overrides) for name, overrides in config["robustness"].items()}
    if len(set(variants.values()) | {official}) != len(variants) + 1:
        raise ValueError("Each strategy parameter combination must be distinct")

    index = nyse_sessions(download_start, end)
    prices, fetched_at, snapshot_hash = load_prices(
        config, "config.yaml", [*universe, reference], download_start, end, index
    )
    print(f"DATA_FETCHED_AT: {fetched_at}", flush=True)
    print(f"DATA_SNAPSHOT_SHA256: {snapshot_hash}", flush=True)
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}", flush=True)
    first = int(index.searchsorted(start))
    split = int(index.searchsorted(is_end, side="right"))
    last = len(index)
    if first < 1 or split - first < 2 or last - split < 2:
        raise ValueError("Insufficient data for the requested IS and OOS split")
    is_schedule = rebalance_schedule(index[:split], first, split, lag)
    full_schedule = rebalance_schedule(index, first, last, lag)
    closes = prices["Close"][universe].to_numpy()
    adjusted = prices["Adj Close"]
    distributions = prices["Distribution"][universe].to_numpy()
    release_days = index.searchsorted(index + pd.Timedelta(days=cash_release_days))

    # Slice before computing the sensitivity returns and targets.
    is_returns = adjusted[universe].iloc[:split].pct_change(fill_method=None).to_numpy()
    risk_free_is = adjusted[reference].iloc[:split].pct_change(fill_method=None).to_numpy()[first:]
    is_execution_inputs = (index[:split], closes[:split], distributions[:split], release_days[:split], first)
    print("ROBUSTNESS (IS only)", flush=True)
    for name, spec in variants.items():
        targets = schur_targets(is_returns, is_schedule, spec, config)
        daily_results = simulate(*is_execution_inputs, targets, spec.friction, cash_buffer)
        print(f"  {name}: {json.dumps(metrics(daily_results, risk_free_is), allow_nan=False)}", flush=True)

    minimum_variance_targets = rolling_targets(
        is_returns, is_schedule, official.lookback_sessions, config["shrinkage"],
        lambda cov: minimum_variance(cov)[0],
    )
    minimum_variance_daily = simulate(*is_execution_inputs, minimum_variance_targets, official.friction, cash_buffer)
    print(f"IS COMPARATOR (full-universe minimum variance): "
          f"{json.dumps(metrics(minimum_variance_daily, risk_free_is), allow_nan=False)}", flush=True)

    returns = adjusted[universe].pct_change(fill_method=None).to_numpy()
    risk_free = adjusted[reference].pct_change(fill_method=None).to_numpy()[first:]
    targets = schur_targets(returns, full_schedule, official, config)
    execution_inputs = (index, closes, distributions, release_days, first)
    daily_results = simulate(*execution_inputs, targets, official.friction, cash_buffer)
    equal_weight = np.full(len(universe), 1 / len(universe))
    benchmark_targets = dict.fromkeys(full_schedule, equal_weight)
    benchmark_daily = simulate(
        *execution_inputs, benchmark_targets, official.friction, cash_buffer,
    )
    periods = period_metrics(daily_results, risk_free, split - first)
    benchmark = period_metrics(benchmark_daily, risk_free, split - first)
    for period in ("is", "oos", "full"):
        print(f"{period.upper()}: {json.dumps(periods[period], allow_nan=False)}")
        print(f"BENCHMARK {period.upper()} (monthly equal weight): {json.dumps(benchmark[period], allow_nan=False)}")
    minimum_fill_cash = {}
    for name, daily in (("strategy", daily_results), ("benchmark", benchmark_daily)):
        fractions = daily["cash_fraction_at_fill"].dropna()
        minimum_fill_cash[name] = float(fractions.min()) if len(fractions) else None
    print(f"MIN_POST_FILL_CASH_FRACTION: {json.dumps(minimum_fill_cash, allow_nan=False)}")
    print(f"PARAM_COMBOS_TRIED: {1 + len(variants)}")
    result = {
        "strategy": config["strategy"],
        "data_range": {"start": str(index[first].date()), "end": str(index[-1].date())},
        **periods,
        "benchmark": {"name": "monthly_equal_weight", **benchmark},
    }
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(9 * 60)
    try:
        main()
    finally:
        signal.alarm(0)
